import math


def matrix_product(left, right):
    def shape(matrix):
        if not isinstance(matrix, list) or not matrix or any(not isinstance(row, list) or not row for row in matrix):
            raise ValueError("invalid matrix")
        width = len(matrix[0])
        if any(len(row) != width for row in matrix):
            raise ValueError("ragged matrix")
        for row in matrix:
            for value in row:
                if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
                    raise ValueError("invalid entry")
        return len(matrix), width

    left_rows, left_cols = shape(left)
    right_rows, right_cols = shape(right)
    if left_cols != right_rows:
        raise ValueError("incompatible dimensions")
    result = [[0] * right_cols] * left_rows
    for i in range(left_rows):
        for j in range(right_cols):
            for k in range(left_cols):
                result[i][j] += left[i][k] * right[k][j]
    return result
```

